// SPDX-License-Identifier: AGPL-3.0-only
//! CAP-12 (signals): the opt-in GLONASS, BeiDou and Galileo E6 bands of the `spectrum` kind,
//! under the bars of `docs/design/evidence/spectrum-bands/PREREGISTRATION.md` (committed before
//! the code existed).
//!
//! S1 holds each band to its interface control document. S2 checks the unit-area densities.
//! S3 checks that the IQ layer's own codes, generated by `iq::scene` and measured by
//! `spectrum::welch_psd`, have the spectrum the model draws. S4 checks the C/N0 path identity.
//! S5 (additivity) is shown by the existing spectrum tests and goldens and by a before/after
//! run of the spectrum scenarios, recorded in `RESULTS.md`.
//!
//! Choices left open by the registration, fixed before the first run: the S3 waveforms are
//! sampled at 16 MS/s for 30 ms, so that a Welch bin (3.9 kHz) spans several of the codes'
//! 1 kHz spectral lines, which the model does not represent.
//!
//! PIN-SCOPE:    the transcribed ICD values (carriers, chip rates, received powers) of the new
//!               bands, and the numerical PSD checks.
//! PIN-EXCLUDES: the existing bands, which their own tests pin.

use kshana::iq::scene::{
    NavData, NoiseConfig, RangeProfile, SatGeometry, Scene, SceneConfig, SceneSatellite,
};
use kshana::iq::signals::{beidou, glonass, SignalCode};
use kshana::iq::{Cf64, SampleSpec, SpreadingCode, VecSink};
use kshana::jamming::effective_cn0_dbhz;
use kshana::navsignal::{q_from_ssc, Modulation};
use kshana::spectrum::{
    default_band, effective_cn0_multi_dbhz, noise_density_dbw_per_hz, psd_nulls_hz, welch_psd,
    Band, JammerCfg, Waveform, BAND_NAMES, GLONASS_CHANNELS, MORE_BAND_NAMES,
};

/// (name, carrier Hz, chip rate Hz, minimum received power dBW, source).
fn expected() -> Vec<(String, f64, f64, f64, &'static str)> {
    let mut v = vec![
        // BDS-SIS-ICD-B1I-3.0 §3 (1561.098 MHz, 2.046 Mcps) and §4.2.5 (−163 dBW).
        (
            "beidou-b1i".to_string(),
            1561.098e6,
            2.046e6,
            -163.0,
            "BDS B1I 3.0",
        ),
        // BDS-SIS-ICD-B1C-1.0 (1575.42 MHz, 1.023 Mcps) and Table 4-4 (MEO −159 dBW).
        (
            "beidou-b1c".to_string(),
            1575.42e6,
            1.023e6,
            -159.0,
            "BDS B1C 1.0",
        ),
        // BDS-SIS-ICD-B2a-1.0 (1176.45 MHz, 10.23 Mcps) and Table 4-4 (MEO −156 dBW).
        (
            "beidou-b2a".to_string(),
            1176.45e6,
            10.23e6,
            -156.0,
            "BDS B2a 1.0",
        ),
        // BDS-SIS-ICD-B3I-1.0 (1268.52 MHz, 10.23 Mcps) and §4.2.5 (−163 dBW).
        (
            "beidou-b3i".to_string(),
            1268.52e6,
            10.23e6,
            -163.0,
            "BDS B3I 1.0",
        ),
        // Galileo OS SIS ICD 2.1 §2.3.2 (1278.75 MHz, 5.115 Mcps) and Table 12 (−155.25 dBW).
        (
            "galileo-e6".to_string(),
            1278.75e6,
            5.115e6,
            -155.25,
            "Galileo OS SIS ICD 2.1",
        ),
    ];
    // GLONASS ICD Ed. 5.1 §3.3.1.1 (f0 + K·Δf), 0.511 Mcps, §3.3.1.6 (−161 / −167 dBW).
    for k in GLONASS_CHANNELS {
        let (l1, l2) = (1602.0e6 + k as f64 * 562.5e3, 1246.0e6 + k as f64 * 437.5e3);
        v.push((
            format!("glonass-l1of-k{k}"),
            l1,
            0.511e6,
            -161.0,
            "GLONASS 5.1",
        ));
        v.push((
            format!("glonass-l2of-k{k}"),
            l2,
            0.511e6,
            -167.0,
            "GLONASS 5.1",
        ));
    }
    v.push((
        "glonass-l1of".into(),
        1602.0e6,
        0.511e6,
        -161.0,
        "GLONASS 5.1",
    ));
    v.push((
        "glonass-l2of".into(),
        1246.0e6,
        0.511e6,
        -167.0,
        "GLONASS 5.1",
    ));
    v
}

/// S1: every new name resolves to its ICD values; the default set is unchanged.
#[test]
fn s1_new_bands_carry_their_icd_values() {
    assert_eq!(
        BAND_NAMES,
        &["gps-l1ca", "galileo-e1", "gps-l2c", "gps-l5", "galileo-e5a"],
        "the default band set must not change"
    );
    let mut fails = Vec::new();
    for (name, f, rc, p, src) in expected() {
        let Some(b) = default_band(&name) else {
            fails.push(format!("{name}: not resolved"));
            continue;
        };
        if (b.centre_hz - f).abs() > 1.0
            || (b.modulation.chip_rate_hz() / rc - 1.0).abs() > 1e-12
            || b.signal_power_dbw != p
        {
            fails.push(format!(
                "{name} ({src}): {} Hz, {} chip/s, {} dBW",
                b.centre_hz,
                b.modulation.chip_rate_hz(),
                b.signal_power_dbw
            ));
        }
    }
    for n in MORE_BAND_NAMES {
        assert!(default_band(n).is_some(), "{n}");
    }
    for bad in [
        "glonass-l1of-k7",
        "glonass-l1of-k-8",
        "glonass-l2of-kx",
        "beidou-b2b",
    ] {
        assert!(default_band(bad).is_none(), "{bad} must be refused");
    }
    assert!(fails.is_empty(), "S1 missed: {fails:?}");
}

/// Area of `b`'s unit density over ±50 chip rates (trapezoid on a fine grid; it is even).
fn area_50(b: &Band) -> f64 {
    let rc = b.modulation.chip_rate_hz();
    let n = 2_000_000usize;
    let h = 50.0 * rc / n as f64;
    2.0 * (0..=n)
        .map(|i| {
            let w = if i == 0 || i == n { 0.5 } else { 1.0 };
            w * b.unit_psd(i as f64 * h)
        })
        .sum::<f64>()
        * h
}

/// S2 as registered: unit area, BPSK first nulls at the chip rate, and B1C equal to Galileo E1.
#[test]
#[ignore = "FINDING F1 (run 2026-10-13): the area part of S2 cannot be met as written. A unit-area density carries power outside +-50 chip rates (a BPSK sinc^2 keeps 2.03e-3 of it there), so its area over that span is 0.997974 for every BPSK band and 0.990083 for B1C (MBOC), against the 1e-3 bar. The null and B1C = E1 parts are met (s2_nulls_and_b1c_parts); the BPSK areas equal the closed-form in-band fraction (finding_s2_areas_are_the_closed_form_in_band_fraction)"]
fn s2_closed_form_densities() {
    let mut fails = Vec::new();
    for name in MORE_BAND_NAMES {
        let b = default_band(name).unwrap();
        let rc = b.modulation.chip_rate_hz();
        let area = area_50(&b);
        if (area - 1.0).abs() > 1e-3 {
            fails.push(format!("{name}: area {area:.6}"));
        }
        if let Modulation::BpskR { .. } = b.modulation {
            let null = psd_nulls_hz(&b.modulation, 1.5 * rc)[0];
            if (null / rc - 1.0).abs() > 1e-3 {
                fails.push(format!("{name}: first null {null} Hz vs {rc}"));
            }
        }
    }
    let (b1c, e1) = (
        default_band("beidou-b1c").unwrap(),
        default_band("galileo-e1").unwrap(),
    );
    for i in 0..200 {
        let f = -15e6 + 30e6 * i as f64 / 199.0;
        let (a, b) = (b1c.unit_psd(f), e1.unit_psd(f));
        if (a - b).abs() > 1e-15 * b.abs().max(1e-300) {
            fails.push(format!("B1C vs E1 at {f} Hz: {a} vs {b}"));
        }
    }
    assert!(fails.is_empty(), "S2 missed: {fails:?}");
}

/// The S2 parts that were met: BPSK first nulls at the chip rate, and B1C equal to Galileo E1.
#[test]
fn s2_nulls_and_b1c_parts() {
    for name in MORE_BAND_NAMES {
        let b = default_band(name).unwrap();
        if let Modulation::BpskR { .. } = b.modulation {
            let rc = b.modulation.chip_rate_hz();
            let null = psd_nulls_hz(&b.modulation, 1.5 * rc)[0];
            assert!((null / rc - 1.0).abs() <= 1e-3, "{name}: {null}");
        }
    }
    let (b1c, e1) = (
        default_band("beidou-b1c").unwrap(),
        default_band("galileo-e1").unwrap(),
    );
    for i in 0..200 {
        let f = -15e6 + 30e6 * i as f64 / 199.0;
        assert!((b1c.unit_psd(f) - e1.unit_psd(f)).abs() <= 1e-15 * e1.unit_psd(f).max(1e-300));
    }
}

/// Pins finding F1 and shows the densities are right: over ±50 chip rates each BPSK band's
/// area equals the closed-form in-band fraction `navsignal::bpsk_power_in_band_closed_form`
/// (POST HOC, added after the registered run).
#[test]
fn finding_s2_areas_are_the_closed_form_in_band_fraction() {
    for name in MORE_BAND_NAMES {
        let b = default_band(name).unwrap();
        let area = area_50(&b);
        match b.modulation {
            Modulation::BpskR { .. } => {
                let rc = b.modulation.chip_rate_hz();
                let eta = kshana::navsignal::bpsk_power_in_band_closed_form(rc, 100.0 * rc);
                assert!((area - eta).abs() < 1e-6, "{name}: {area} vs {eta}");
                assert!((area - 0.997974).abs() < 1e-6, "{name}: {area}");
            }
            _ => assert!((area - 0.990083).abs() < 1e-6, "{name}: {area}"),
        }
    }
}

/// A noise-free `iq::scene` waveform of `code` at 16 MS/s for 30 ms, data off, Doppler 0.
fn waveform(code: SignalCode) -> Vec<Cf64> {
    let fs = 16.0e6;
    let spec = SampleSpec {
        fs_hz: fs,
        center_hz: code.carrier_hz(),
        if_hz: 0.0,
    };
    let mut cfg = SceneConfig::new(spec, 0.030);
    cfg.noise = NoiseConfig {
        enabled: false,
        ..cfg.noise
    };
    cfg.threads = 2;
    let mut scene = Scene::new(cfg).unwrap();
    scene.add_satellite(SceneSatellite {
        id: 1,
        code: Box::new(code),
        geometry: SatGeometry::Profile(RangeProfile {
            range_m: 2.1e7,
            range_rate_mps: 0.0,
            range_accel_mps2: 0.0,
            elevation_deg: 45.0,
            azimuth_deg: 0.0,
        }),
        cn0_dbhz: Some(45.0),
        nav: NavData::None,
    });
    let mut sink = VecSink::default();
    let mut truth = Vec::new();
    scene.generate(&mut sink, &mut truth).unwrap();
    sink.samples
}

/// Mean |10·log10(measured/model)| over `keep` bins, both normalised to unit sum over them.
fn lobe_error_db(
    x: &[Cf64],
    model: impl Fn(f64) -> f64,
    keep: impl Fn(f64) -> bool,
) -> (f64, usize) {
    let w = welch_psd(x, 16.0e6, 4096, 0.5).unwrap();
    assert!(w.segments >= 200, "{} segments", w.segments);
    let idx: Vec<usize> = (0..w.freq_hz.len())
        .filter(|&i| keep(w.freq_hz[i]))
        .collect();
    let sm: f64 = idx.iter().map(|&i| w.psd[i]).sum();
    let sr: f64 = idx.iter().map(|&i| model(w.freq_hz[i])).sum();
    let err = idx
        .iter()
        .map(|&i| (10.0 * ((w.psd[i] / sm) / (model(w.freq_hz[i]) / sr)).log10()).abs())
        .sum::<f64>()
        / idx.len() as f64;
    (err, idx.len())
}

/// The three S3 errors (mean |Δ| dB): GLONASS L1OF, BeiDou B1I, BeiDou B1C data.
fn s3_errors() -> [(&'static str, f64); 3] {
    let bpsk = |name: &str, code: SignalCode| {
        let b: Band = default_band(name).unwrap();
        let rc = b.modulation.chip_rate_hz();
        lobe_error_db(&waveform(code), |f| b.unit_psd(f), |f| f.abs() <= 0.96 * rc).0
    };
    let m = Modulation::BocSin { m: 1.0, n: 1.0 };
    let rc = m.chip_rate_hz();
    let boc = lobe_error_db(
        &waveform(beidou::b1c_data(19).unwrap()),
        |f| m.psd(f),
        |f| f.abs() >= 0.04 * rc && f.abs() <= 1.96 * rc,
    )
    .0;
    [
        (
            "glonass-l1of",
            bpsk("glonass-l1of", glonass::l1of(0).unwrap()),
        ),
        ("beidou-b1i", bpsk("beidou-b1i", beidou::b1i(1).unwrap())),
        ("beidou-b1c data (BOC(1,1))", boc),
    ]
}

/// Pins finding F2.
#[test]
fn finding_s3_per_bin_errors_follow_the_code_line_spectrum() {
    let e = s3_errors();
    for ((name, got), want) in e.iter().zip([0.074, 1.260, 1.560]) {
        assert!((got - want).abs() < 0.005, "{name}: {got:.3} dB vs {want}");
    }
}

/// POST HOC, REPORTED, NOT GATING (added after the registered run): the measured/model power
/// ratio averaged over quarter-chip-rate bands of the main lobe, and the per-bin scatter.
#[test]
fn posthoc_s3_band_averaged_shape() {
    for (label, code, m) in [
        (
            "beidou-b1i",
            beidou::b1i(1).unwrap(),
            Modulation::BpskR { n: 2.0 },
        ),
        (
            "beidou-b1c data",
            beidou::b1c_data(19).unwrap(),
            Modulation::BocSin { m: 1.0, n: 1.0 },
        ),
        (
            "glonass-l1of",
            glonass::l1of(0).unwrap(),
            Modulation::BpskR { n: 0.511 / 1.023 },
        ),
    ] {
        let w = welch_psd(&waveform(code), 16.0e6, 4096, 0.5).unwrap();
        let rc = m.chip_rate_hz();
        let idx: Vec<usize> = (0..w.freq_hz.len())
            .filter(|&i| w.freq_hz[i].abs() <= 2.0 * rc)
            .collect();
        let sm: f64 = idx.iter().map(|&i| w.psd[i]).sum();
        let sr: f64 = idx.iter().map(|&i| m.psd(w.freq_hz[i])).sum();
        let mut out = String::new();
        for k in 0..8 {
            let (lo, hi) = (k as f64 * 0.25 * rc, (k + 1) as f64 * 0.25 * rc);
            let sel: Vec<usize> = idx
                .iter()
                .copied()
                .filter(|&i| w.freq_hz[i].abs() >= lo && w.freq_hz[i].abs() < hi)
                .collect();
            let a: f64 = sel.iter().map(|&i| w.psd[i] / sm).sum();
            let b: f64 = sel.iter().map(|&i| m.psd(w.freq_hz[i]) / sr).sum();
            out += &format!(
                " [{:.2}-{:.2} Rc] {:+.2} dB",
                lo / rc,
                hi / rc,
                10.0 * (a / b).log10()
            );
        }
        let r: Vec<f64> = idx
            .iter()
            .copied()
            .filter(|&i| w.freq_hz[i].abs() > 0.1 * rc && w.freq_hz[i].abs() < 0.9 * rc)
            .map(|i| 10.0 * ((w.psd[i] / sm) / (m.psd(w.freq_hz[i]) / sr)).log10())
            .collect();
        let mean = r.iter().sum::<f64>() / r.len() as f64;
        let sd = (r.iter().map(|v| (v - mean).powi(2)).sum::<f64>() / r.len() as f64).sqrt();
        eprintln!("POST-HOC S3 {label}:{out}; per-bin dB in 0.1-0.9 Rc mean {mean:+.2} sd {sd:.2}");
        assert!(mean.is_finite() && sd.is_finite());
    }
}

/// S3 as registered: the IQ layer's GLONASS L1OF, BeiDou B1I and B1C data waveforms have the
/// model's shape.
#[test]
#[ignore = "FINDING F2 (run 2026-10-13): GLONASS L1OF met (0.074 dB); BeiDou B1I 1.260 dB and B1C data 1.560 dB miss the 0.5 dB bar. Averaged over quarter-chip-rate bands the B1I shape is within +-0.25 dB of the model across the main lobe and B1C within +-0.1 dB up to 1.75 R_c: the per-bin error is the Gold and Weil codes' uneven spectral-line powers (per-bin sd 1.49 and 0.52 dB; the GLONASS m-sequence has equal lines, 0.09 dB), plus, for B1C, bins next to the BOC(1,1) null at 2 R_c (+5.8 dB over 1.75-2 R_c). Pinned by finding_s3_per_bin_errors_follow_the_code_line_spectrum"]
fn s3_iq_layer_waveforms_match_the_model_spectrum() {
    let mut fails = Vec::new();
    for (name, err) in s3_errors() {
        eprintln!("S3 {name}: mean |Δ| {err:.3} dB");
        if err > 0.5 {
            fails.push(format!("{name}: {err:.3} dB"));
        }
    }
    assert!(fails.is_empty(), "S3 missed: {fails:?}");
}

/// S4: for each new band, CW and matched jammers at J/S 30 dB give the same C/N0 by the
/// spectral separation coefficient and by `jamming::effective_cn0_dbhz` with `Q = 1/(R_c κ)`.
#[test]
fn s4_cn0_paths_agree_on_the_new_bands() {
    let n0 = noise_density_dbw_per_hz(290.0);
    let mut worst = 0.0f64;
    for name in MORE_BAND_NAMES {
        let b = default_band(name).unwrap();
        let rc = b.modulation.chip_rate_hz();
        for waveform in [Waveform::Cw, Waveform::Matched] {
            let j = JammerCfg {
                name: None,
                waveform,
                centre_mhz: b.centre_hz / 1e6,
                bandwidth_mhz: None,
                sweep_period_us: None,
                matched_to: (waveform == Waveform::Matched).then(|| name.to_string()),
                received_power_dbw: Some(b.signal_power_dbw + 30.0),
                eirp_dbw: None,
                range_m: None,
                rx_gain_dbi: 0.0,
                on_s: 0.0,
                off_s: None,
            }
            .resolve(0, std::slice::from_ref(&b))
            .unwrap();
            let js = j.js_db(&b);
            assert!((js - 30.0).abs() < 1e-9, "{name}: J/S {js}");
            let cn0 = b.nominal_cn0_dbhz(n0);
            let kappa = j.ssc(&b, 0.0, 1.0);
            let ours = effective_cn0_multi_dbhz(cn0, &[(js, kappa)]);
            let theirs = effective_cn0_dbhz(cn0, js, q_from_ssc(kappa, rc), rc);
            worst = worst.max((ours - theirs).abs());
        }
    }
    eprintln!("S4: worst difference {worst:.2e} dB");
    assert!(worst <= 1e-9, "S4 missed: {worst:e} dB");
}
